// memmove. The game imports it from the C runtime and 9.x does not export it
// under that name, so it is written here rather than forwarded. Overlap is the
// whole point of the function -- Mem::Move would do, but it is one more import
// to resolve and this is eight instructions.
extern "C" void *gate6_mem_move(void *dst, const void *src, u32 n)
{
    u8 *d = (u8 *)dst;
    const u8 *s = (const u8 *)src;
    if (d == s || !n)
        return dst;
    if (d < s)
        for (u32 i = 0; i < n; i++) d[i] = s[i];
    else
        for (u32 i = n; i-- > 0; ) d[i] = s[i];
    return dst;
}

static void panic(const u16 *cat, int catLen, int reason)
{
    Ptrc16 d;
    d.lengthAndType = ((u32)EPtrC << KTypeShift) | (u32)catLen;
    d.text = cat;
    user_panic(&d, reason);
}

#define PANIC(name, reason) do { \
    static const u16 s[] = name; \
    panic(s, (int)(sizeof s / sizeof s[0]), (reason)); } while (0)

#define CAT_FS  {'G','6','F','S'}
// A write that failed, and which file it was: the log or the box. The reason
// is the file server's own error code, negated as Symbian returns it.
#define CAT_WRITE {'G','6','W','R'}
enum { LOUD_WRITE_ERRORS = 1 };
enum { EXACT_BYTES = 768 };   // 96 records written one at a time
#define CAT_BOXW  {'G','6','B','W'}
#define CAT_MEM {'G','6','M','E','M'}
#define CAT_HDR {'G','6','H','D','R'}
#define CAT_IMP {'G','6','I','M','P'}
#define CAT_RET {'G','6','R','E','T'}
#define CAT_LIB {'G','6','L','I','B'}
#define CAT_SHIM {'G','6','S','H','M'}
#define CAT_NUL {'G','6','N','U','L'}
#define CAT_PURE {'G','6','P','U','R'}

// The EKA1 header, at the offsets EKA2L1's loader reads.
struct E32 {
    u32 uid1, uid2, uid3, check, sig, cpu;
    u32 pad, compression, petran, timeLo, timeHi;
    u32 flags, codeSize, dataSize, heapMin, heapMax, stackSize, bssSize;
    u32 entryPoint, codeBase, dataBase, dllRefCount;
    u32 exportDirOffset, exportDirCount, textSize;
    u32 codeOffset, dataOffset, importOffset, codeRelocOffset, dataRelocOffset;
};


// The two layouts the game's files can sit in, and the drives to look on.
// These are what the loader *searches*; what the game is *told* is always the
// `E:` form of whichever layout was found -- see kPath2 and kPath0 below and
// `gate6_dll_name`.
//
// Round 79's question was whether the port survives an install to phone
// memory. It did not, for three separate reasons, and only one of them was
// ours: the search tried `E:\system\apps\6rbc\`, `E:\6rbc.app` and
// `C:\6rbc.app` and never `C:\system\apps\6rbc\`, which is the layout a
// C: install actually uses.
static const u16 kLayoutApps[] = {'?',':','\\','s','y','s','t','e','m','\\','a','p','p','s','\\',
                                  GAME_STEM_CHARS,'\\',GAME_STEM_CHARS,'.','a','p','p'};
static const u16 kLayoutRoot[] = {'?',':','\\',GAME_STEM_CHARS,'.','a','p','p'};
// E first, because that is where every install so far has put it and a hit on
// the first candidate costs one open. C next, then the mass-memory letters.
static const u16 kDrives[] = { 'E', 'C', 'F', 'D', 'G', 'H' };
// What `build_release.py` XORs the front of the image with, and what the
// loader XORs back. Any value does; this one is not zero and not 0xff, so a
// mistake shows up as noise rather than as the original or as a blank.
enum { IMAGE_SCRAMBLE = 0xA5, IMAGE_SCRAMBLE_BYTES = 32 };

// The other two reasons were the game's, and they are why the answer is not
// "teach the port about C:" but "never tell the game about anything but E:".
//
// One: the game has absolute `E:` paths compiled into it -- the prefix
// `E:\system\apps\6RBC\Streams\` that it joins the bgm_*.swav names onto,
// and three full paths beside it. Those cannot be made relative.
//
// Two, and the one that would have been found the hard way: the BiNPDA
// loader's read-only-card protection tests the **letter**, not the directory
// (see `name_on_the_card`). Move the game to C: and the protection stops
// firing, and a game that finds its own drive writable is a game that has
// decided it is not on a card.
//
// So the game is told `E:` whatever drive it is really on, and the three file
// calls the protection replaced translate `E:` to the real drive on the way
// through. On the usual E: install the translation is the identity and
// nothing changes at all.
static const u16 kPath0[] = {'E',':','\\',GAME_STEM_CHARS,'.','a','p','p'};
static const u16 kPath2[] = {'E',':','\\','s','y','s','t','e','m','\\','a','p','p','s','\\',
                             GAME_STEM_CHARS,'\\',GAME_STEM_CHARS,'.','a','p','p'};

// Every import points here, through a 16-byte stub carrying its own report
// code. That code is `import count * 1000 + index`, because a panic gives us
// one integer and which binary was loaded is half the answer: this game ships
// both as a 1.6 MB image with 462 imports and as a 4 KB loader stub with 41,
// and an index alone cannot tell them apart. Keeping it in the stub also keeps
// this program free of writable globals, which the image has no room for --
// it declares no .bss.
extern "C" void gate6_report(int code)
{
    PANIC(CAT_IMP, code);
}

// A call through a vtable slot the old binary never filled in -- or one of
// the port's stand-in slots it left unmapped (GC_NONE and the like). Round
// 128 showed `G6PUR 0` and nothing else: this has no context to log with.
// So the reason is the caller's return address, raw: an address in the game's
// image (the log's `image loaded at` record gives the base) names the call site, and
// one in the ROM names the 9.x caller.
extern "C" void gate6_pure_virtual()
{
    PANIC(CAT_PURE, (int)(u32)__builtin_return_address(0));
}

// Only the 16-bit Mem::Compare is still exported, so the 8-bit one lives here.
// Symbian's contract: compare the common prefix, then the lengths.
// ---------------------------------------------------------------------------
// **EKA1's TInt64, round 125.** A class of two words, {TUint iLow; TInt
// iHigh}, with its arithmetic exported from euser; 9.x made it a long long
// and exports nothing. One imports the class: operator+= (`this` in r0, the
// operand in r1, returns `this`), the three that make a new TInt64 -- the
// game passes a hidden result pointer in r0, `this` in r1, the operand in
// r2, and expects r0 back (0x11a2c, 0x119d8, 0x119c4) -- the two
// comparisons, GetTInt and GetTReal. All in 32-bit halves: nothing here may
// pull in a runtime helper the loader does not link.
static inline u32 i64_add(u32 *lo, u32 *hi, u32 blo, u32 bhi)
{
    const u32 l = *lo + blo;
    *hi = *hi + bhi + (l < *lo ? 1u : 0u);
    *lo = l;
    return l;
}

static inline void i64_sub(u32 *lo, u32 *hi, u32 blo, u32 bhi)
{
    const u32 borrow = (*lo < blo) ? 1u : 0u;
    *lo -= blo;
    *hi = *hi - bhi - borrow;
}

static inline void i64_neg(u32 *lo, u32 *hi)
{
    *lo = ~*lo + 1u;
    *hi = ~*hi + (*lo == 0u ? 1u : 0u);
}

static inline int i64_lt(u32 alo, u32 ahi, u32 blo, u32 bhi)
{
    if (ahi != bhi) return (int)ahi < (int)bhi;
    return alo < blo;
}

extern "C" u32 *gate6_tint64_add(u32 *a, const u32 *b)           // a += b
{
    i64_add(&a[0], &a[1], b[0], b[1]);
    return a;
}

extern "C" u32 *gate6_tint64_sub(u32 *out, const u32 *a, const u32 *b)   // out = a - b
{
    u32 lo = a[0], hi = a[1];
    i64_sub(&lo, &hi, b[0], b[1]);
    out[0] = lo; out[1] = hi;
    return out;
}

extern "C" u32 *gate6_tint64_mul(u32 *out, const u32 *a, const u32 *b)   // out = a * b, low 64 bits
{
    const unsigned long long p = (unsigned long long)a[0] * b[0];   // umull, no helper
    out[0] = (u32)p;
    out[1] = (u32)(p >> 32) + a[1] * b[0] + a[0] * b[1];
    return out;
}

// Unsigned long division, a bit at a time: 64 steps of shift and compare.
static void u64_div(u32 nlo, u32 nhi, u32 dlo, u32 dhi, u32 *qlo, u32 *qhi)
{
    u32 rlo = 0, rhi = 0, ql = 0, qh = 0;
    for (int i = 63; i >= 0; i--) {
        rhi = (rhi << 1) | (rlo >> 31);
        rlo = (rlo << 1) | ((i >= 32 ? (nhi >> (i - 32)) : (nlo >> i)) & 1u);
        if (rhi > dhi || (rhi == dhi && rlo >= dlo)) {
            i64_sub(&rlo, &rhi, dlo, dhi);
            if (i >= 32) qh |= 1u << (i - 32); else ql |= 1u << i;
        }
    }
    *qlo = ql; *qhi = qh;
}

extern "C" u32 *gate6_tint64_div(u32 *out, const u32 *a, const u32 *b)   // out = a / b, towards zero
{
    u32 alo = a[0], ahi = a[1], blo = b[0], bhi = b[1];
    const int neg = ((ahi ^ bhi) & 0x80000000u) != 0;
    if ((int)ahi < 0) i64_neg(&alo, &ahi);
    if ((int)bhi < 0) i64_neg(&blo, &bhi);
    u32 qlo = 0, qhi = 0;
    if (blo | bhi)                      // a divide by zero answers 0 rather than panicking the game
        u64_div(alo, ahi, blo, bhi, &qlo, &qhi);
    if (neg) i64_neg(&qlo, &qhi);
    out[0] = qlo; out[1] = qhi;
    return out;
}

extern "C" int gate6_tint64_ge(const u32 *a, const u32 *b) { return !i64_lt(a[0], a[1], b[0], b[1]); }
extern "C" int gate6_tint64_lt(const u32 *a, const u32 *b) { return i64_lt(a[0], a[1], b[0], b[1]); }

// TInt64::GetTReal(): the IEEE double, rounded to nearest even, answered in
// r0:r1 in the game's FPA order (the sign-and-exponent word first), which a
// 64-bit integer return puts there without any double crossing a helper.
extern "C" unsigned long long gate6_tint64_real(const u32 *a)
{
    u32 lo = a[0], hi = a[1];
    const u32 sign = hi & 0x80000000u;
    if (sign) i64_neg(&lo, &hi);
    if (!(lo | hi)) return 0;
    int n = 63;                                     // the top set bit
    while (!((n >= 32 ? hi >> (n - 32) : lo >> n) & 1u)) n--;
    u32 mlo, mhi;                                   // the 53-bit mantissa, top bit at bit 52
    u32 e = 1023u + (u32)n;
    if (n > 52) {
        const u32 sh = (u32)(n - 52);               // 1..11
        mlo = (lo >> sh) | (hi << (32 - sh));
        mhi = hi >> sh;
        const u32 rem = lo & ((1u << sh) - 1u), half = 1u << (sh - 1);
        if (rem > half || (rem == half && (mlo & 1u))) {
            if (++mlo == 0u) mhi++;
            if (mhi == 0x00200000u) { mhi = 0x00100000u; e++; }
        }
    } else {
        const u32 sh = (u32)(52 - n);               // 0..52
        if (sh >= 32)      { mhi = lo << (sh - 32); mlo = 0; }
        else if (sh == 0)  { mhi = hi; mlo = lo; }
        else               { mhi = (hi << sh) | (lo >> (32 - sh)); mlo = lo << sh; }
    }
    const u32 dhi = sign | (e << 20) | (mhi & 0x000FFFFFu);
    return ((unsigned long long)mlo << 32) | dhi;   // r0 = dhi, r1 = mlo
}

extern "C" int gate6_mem_compare(const u8 *a, int la, const u8 *b, int lb)
{
    const int n = (la < lb) ? la : lb;
    for (int i = 0; i < n; i++)
        if (a[i] != b[i])
            return (int)a[i] - (int)b[i];
    return la - lb;
}

